from langchain_core.output_parsers.openai_functions import JsonOutputFunctionsParser
from langgraph.graph import END, StateGraph
from langgraph.prebuilt import ToolNode
import os
import functools
import json
from typing import Any, Dict, List, Optional, Sequence, Literal, TypedDict
from langchain_core.pydantic_v1 import BaseModel, Field, validator

from langchain_core.prompts import ChatPromptTemplate
from langchain_core.messages import BaseMessage, HumanMessage, SystemMessage, AIMessage, FunctionMessage, ToolMessage
from langchain_google_vertexai import ChatVertexAI, create_structured_runnable

def _convert_to_prompt(part: str) -> Dict[str, Any]:
    return {"text": part}

def _convert_to_parts(message: BaseMessage) -> List[Dict[str, Any]]:
    raw_content = message.content
    if isinstance(raw_content, str):
        raw_content = [raw_content]
    return [_convert_to_prompt(part) for part in raw_content]

def convert_messages_to_vertex_format(history: List[BaseMessage], convert_system_message_to_human: bool = False):
    vertex_messages: List[Dict[str, Any]] = []
    system_parts: Optional[List[Dict[str, Any]]] = None
    system_instruction = None
    prev_ai_message: Optional[AIMessage] = None

    for i, message in enumerate(history):
        if isinstance(message, SystemMessage):
            prev_ai_message = None
            if i != 0:
                raise ValueError("SystemMessage should be the first in the history.")
            if system_instruction is not None:
                raise ValueError(
                    "Detected more than one SystemMessage in the list of messages. "
                    "Gemini APIs support the insertion of only one SystemMessage."
                )
            if convert_system_message_to_human:
                system_parts = _convert_to_parts(message)
                continue
            system_instruction = {"role": "user", "parts": _convert_to_parts(message)}
        elif isinstance(message, HumanMessage):
            prev_ai_message = None
            role = "user"
            parts = _convert_to_parts(message)
            if system_parts is not None:
                if i != 1:
                    raise ValueError(
                        "System message should be immediately followed by HumanMessage"
                    )
                parts = system_parts + parts
                system_parts = None
            vertex_messages.append({"role": role, "parts": parts})
        elif isinstance(message, AIMessage):
            prev_ai_message = message
            role = "model"
            parts = _convert_to_parts(message) if message.content else []
            for tc in message.tool_calls:
                function_call = {"name": tc["name"], "args": tc["args"]}
                parts.append({"function_call": function_call})
            vertex_messages.append({"role": role, "parts": parts})
        elif isinstance(message, FunctionMessage):
            prev_ai_message = None
            role = "function"
            part = {"function_response": {"name": message.name, "response": {"content": message.content}}}
            prev_content = vertex_messages[-1]
            if prev_content and prev_content["role"] == "function":
                parts = list(prev_content["parts"])
                parts.append(part)
                vertex_messages[-1] = {"role": role, "parts": parts}
                continue
            vertex_messages.append({"role": role, "parts": [part]})
        elif isinstance(message, ToolMessage):
            role = "function"
            name = message.name or next(
                (t["name"] for t in prev_ai_message.tool_calls if t["id"] == message.tool_call_id), None
            )
            if not name:
                raise ValueError("Message name is empty and can't find corresponding tool call")
            content = _parse_tool_message_content(message.content)
            part = {"function_response": {"name": name, "response": content}}
            prev_content = vertex_messages[-1]
            if prev_content and prev_content["role"] == "function":
                parts = list(prev_content["parts"])
                parts.append(part)
                vertex_messages[-1] = {"role": role, "parts": parts}
                continue
            vertex_messages.append({"role": role, "parts": [part]})
        else:
            raise ValueError(f"Unexpected message type {type(message)} at position {i}.")
    return system_instruction, vertex_messages

def _parse_tool_message_content(content: Any) -> Dict[Any, Any]:
    if isinstance(content, list):
        parsed_content = [_parse_content(c) for c in content]
        if len(parsed_content) > 1:
            merged_content = {}
            for content_piece in parsed_content:
                for key, value in content_piece.items():
                    if key not in merged_content:
                        merged_content[key] = []
                    merged_content[key].append(value)
            return {k: "".join(v) for k, v in merged_content.items()}
        return parsed_content[0]
    return _parse_content(content)

def _parse_content(raw_content: Any) -> Dict[Any, Any]:
    if isinstance(raw_content, dict):
        return raw_content
    if isinstance(raw_content, str):
        try:
            content = json.loads(raw_content)
            if isinstance(content, dict):
                return content
        except json.JSONDecodeError:
            pass
    return {"content": raw_content}
    
