def reduce_results(left: list[str], right: list[str]) -> list[str]:
    """This approach might not be the best, but it can solve repeat problems."""
    left_table = {result: i for i, result in enumerate(left)}
    merged = left.copy()
    for right_result in right:
        if (existing_idx := left_table.get(right_result)) is not None:
            merged[existing_idx] = right_result
        else:
            merged.append(right_result)
    return merged


class ChildState(TypedDict):
