    def setup_workflow(self):
        """Set up the network search workflow with Redis checkpoint support."""
        logger.info("Setting up network search workflow...")

        # Define the state for the query process
        graph = StateGraph(QueryState)

        def plan_search_queries(state: QueryState):
            generate_queries_prompt = f"""
            {self.main_instructions}

            {self.prompt_instructions}

            Now generate variations for:
            "{state['query']}"
            """

            model = self.answer_helper.main_llm
            response = model.with_structured_output(Queries).invoke(generate_queries_prompt)

            return {"variations": response.queries}

        def execute_search_query_parallel(state: QueryState):
            """Execute search queries in parallel using ThreadPoolExecutor."""
            if not self.solr_url:
                raise ValueError("No Solr URL configured for search")

            logger.info(f"Executing search with URL: {self.solr_url} and queries: {state['variations']} using parallel threads")

            with concurrent.futures.ThreadPoolExecutor() as executor:
                future_to_query = {
                    executor.submit(SolrUtil().get_docs, self.solr_url, query): query
                    for query in state['variations']
                }
                for future in concurrent.futures.as_completed(future_to_query):
                    query = future_to_query[future]
                    try:
                        docs = future.result()
                        if not isinstance(state.get('results'), list):
                            state['results'] = []
                        if isinstance(docs, list):
                            state['results'].append(docs)
                        else:
                            state['results'].append([docs])
                        logger.info(f'Search results for query "{query}": {len(docs)} documents')
                    except Exception as exc:
                        logger.error(f'Query {query} generated an exception: {exc}')

            return {"results": state['results']}

        def aggregate_search_results(state: QueryState):
            # Flatten and deduplicate results based on title
            seen_titles = set()
            combined_results = []

            # Get all results from each query variation
            all_results = state.get('results', [])
            for result_list in all_results:
                if isinstance(result_list, list):
                    for result in result_list:
                        # Access the attributes of the Document object directly
                        title = result.metadata.get('title', '')
                        if title not in seen_titles:
                            seen_titles.add(title)
                            combined_results.append(result)

            logger.info(f"Total combined unique results: {len(combined_results)}")
            return {"combined_results": combined_results}

        def check_remaining_queries(state: QueryState):
            variations = state.get("variations", [])
            if not variations:
                return END
            return [Send("execute_search_query_parallel", {"variations": variations})]

        def generate_final_response(state: QueryState):
            """Process combined results to get the final refined answer."""
            # Reuse an existing solr_helper if already available in state
            if "solr_helper" not in state:
                state["solr_helper"] = SolrHelper(
                    answer_helper=self.answer_helper,
                    query=state["query"],
                    solr_url=self.solr_url
                )
            solr_helper = state["solr_helper"]

            # Update the query field in case it has changed
            solr_helper.query = state["query"]

            # Get the response using the combined results from document aggregation
            final_response = solr_helper.get_solr_search_langraph_results(state["combined_results"])

            logger.info(f"Final response generated: {final_response.get('text', '')}")
            return {"final_answer": final_response}

        # Add nodes and edges
        graph.add_node("plan_search_queries", plan_search_queries)
        graph.add_node("execute_search_query_parallel", execute_search_query_parallel)
        graph.add_node("aggregate_search_results", aggregate_search_results)
        graph.add_node("generate_final_response", generate_final_response)

        # Define the workflow
        graph.add_edge(START, "plan_search_queries")
        graph.add_conditional_edges("plan_search_queries", check_remaining_queries, ["execute_search_query_parallel"])
        graph.add_edge("execute_search_query_parallel", "aggregate_search_results")
        graph.add_edge("aggregate_search_results", "generate_final_response")
        graph.add_edge("generate_final_response", END)

        # Initialize Redis checkpointer
        with RedisSaver.from_conn_url(REDIS_URL) as checkpointer:
            self.checkpointer = checkpointer
            self.workflow_app = graph.compile(checkpointer=self.checkpointer)

        logger.info("Network search workflow setup completed with Redis checkpoint support")

    def store_thread_id(self, session_id: str, thread_id: str):
        """Store the thread_id in Redis for a given session_id."""
        redis_key = f"solar_thread_id_{session_id}"
        try:
            r = redis.Redis.from_url(url=REDIS_URL, decode_responses=True)
            r.set(redis_key, thread_id)
        except Exception as e:
            logger.error(f"Error saving thread ID to Redis: {e}")

    def get_thread_id(self, session_id: str) -> Optional[str]:
        """Retrieve the thread_id from Redis for a given session_id."""
        redis_key = f"solar_thread_id_{session_id}"
        try:
            r = redis.Redis.from_url(url=REDIS_URL, decode_responses=True)
            return r.get(redis_key)
        except Exception as e:
            logger.error(f"Error retrieving thread ID from Redis: {e}")
            return None

    def get_answer(self, query: str, session_id: str, solr_url: str = None) -> dict:
        """Execute the network search workflow with Redis checkpoint support."""
        try:
            total_start_time = time.time()
            if not self.workflow_app:
                raise ValueError("Network search workflow is not initialized.")

            # Update solr_url if provided
