@tool
def natural_language_to_sql(query: str) -> str:
    """Convert natural language to SQL query."""
    return f"SELECT * FROM table WHERE condition LIKE '%{query}%'"

@tool
def rag_agent(query: str) -> str:  
    """Retrieve relevant information using RAG."""
    return f"Retrieved information for: {query}"

class State(MessagesState):
    next: str = ""
    user_query: str = ""
    iterations: int = 0

def supervisor_node(state: State):
    if state.get('iterations', 0) >= 2:
        return {"next": END}
    goto = "natural_language_to_sql_node"
    return {
        "next": goto, 
        "iterations": state.get('iterations', 0) + 1
    }

def natural_language_to_sql_node(state: State):
    user_query = state.get('user_query', 'what is ebs application version?')
    response = llm.invoke([HumanMessage(content=f"Convert this to SQL: {user_query}")])

    return {
        "iterations": state.get('iterations', 0) + 1,
        "messages": [
            response,  
            HumanMessage(content="Processing complete", name="natural_language_to_sql")
        ]
    }

def should_continue(state: State):
    if state.get('iterations', 0) >= 2:
        return END
    return "natural_language_to_sql_node"

builder = StateGraph(State)
memory = MemorySaver()  

builder.add_node("supervisor", supervisor_node)
builder.add_node("natural_language_to_sql_node", natural_language_to_sql_node)
builder.set_entry_point("supervisor") 
builder.add_conditional_edges("supervisor", should_continue)
builder.add_edge("natural_language_to_sql_node", "supervisor")

graph = builder.compile(checkpointer=memory)

